function due(spec,from){if(!spec)return null;if(spec.at){const [hh,mm]=spec.at.split(':').map(Number);return atLocal(from,spec.days||0,hh,mm);}return from+(spec.days||0)*D+(spec.hours||0)*H+(spec.minutes||0)*60000;}
